'use strict';

// MAIN //

/**
* Sorts a strided array using insertion sort according to a provided callback function.
*
* @private
* @param {PositiveInteger} N - number of indexed elements
* @param {Object} x - input array object
* @param {Collection} x.data - input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @param {Callback} clbk - callback function
* @param {*} [thisArg] - execution context
* @returns {Object} `x`
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [ 1.0, -2.0, 3.0, -4.0 ];
*
* function clbk( a, b ) {
*     if ( a < b ) {
*         return -1;
*     }
*     if ( a > b ) {
*         return 1;
*     }
*     return 0;
* }
*
* gsortinsBy( x.length, arraylike2object( toAccessorArray( x ) ), 1, 0, clbk );
*
* console.log( x );
* // => [ -4.0, -2.0, 1.0, 3.0 ]
*/
function gsortinsBy( N, x, strideX, offsetX, clbk, thisArg ) {
	var xbuf;
	var xget;
	var xset;
	var ix;
	var jx;
	var fx;
	var v;
	var u;
	var i;

	// Cache reference to array data:
	xbuf = x.data;

	// Cache references to element accessors:
	xget = x.accessors[ 0 ];
	xset = x.accessors[ 1 ];

	fx = offsetX; // first index
	ix = fx + strideX;

	if ( strideX < 0 ) {
		// Traverse the strided array from right-to-left...
		for ( i = 1; i < N; i++ ) {
			v = xget( xbuf, ix );
			jx = ix - strideX;

			// Shift all larger values to the right of the current element to the left...
			while ( jx <= fx ) {
				u = xget( xbuf, jx );
				if ( clbk.call( thisArg, u, v, x ) <= 0 ) {
					break;
				}
				xset( xbuf, jx+strideX, u );
				jx -= strideX;
			}
			xset( xbuf, jx+strideX, v );
			ix += strideX;
		}
		return x;
	}
	// Traverse the strided array from left-to-right...
	for ( i = 1; i < N; i++ ) {
		v = xget( xbuf, ix );
		jx = ix - strideX;

		// Shift all larger values to the left of the current element to the right...
		while ( jx >= fx ) {
			u = xget( xbuf, jx );
			if ( clbk.call( thisArg, u, v, x ) <= 0 ) {
				break;
			}
			xset( xbuf, jx+strideX, u );
			jx -= strideX;
		}
		xset( xbuf, jx+strideX, v );
		ix += strideX;
	}
	return x;
}


// EXPORTS //

module.exports = gsortinsBy;
